mapper.sql:
where t.revision_id=r.id and t.clan_id=#{criteria.clanId} and r.clan_id=#{criteria.clanId}
 and t.status='pending'and r.submitter_id=#{criteria.actorId}and t.reviewed_at is not null and t.status<>'pending' and t.reviewer_id=#{criteria.actorId}
 and r.target_type=#{criteria.targetType}and r.target_id=#{criteria.targetId}and t.status=#{criteria.status}and t.branch_id=#{criteria.branchId}and r.submit_time>=#{criteria.submittedFrom}and r.submit_time<=#{criteria.submittedTo}and t.reviewed_at>=#{criteria.processedFrom}and t.reviewed_at<=#{criteria.processedTo}
 and t.branch_id in #{id}and false
